  ui_story_31200201_66_dialog_content = "Sekarang, mari kita mulai kontes kecerdasan yang melelahkan ini!",
  ui_story_31200201_67_dialog_content = "Di babak pertama, kontestan harus beradu cepat untuk memencet bel dan menjawab pertanyaan. Tolong dengarkan baik-baik setiap pertanyaannya!",
  ui_story_31200201_68_dialog_content = "Pertanyaan pertama adalah soal matematika.",
  ui_story_31200201_69_dialog_content = "Ada sembilan bola: delapan sama persis, dan yang satu sedikit lebih berat dari yang lain.",
  ui_story_31200201_70_dialog_content = "Setidaknya berapa kali Michenny harus menggunakan timbangannya untuk menemukan bola berat ini? Mulai!",
  ui_story_31200201_71_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_31200201_72_dialog_content = "Brock! Apa jawabanmu?",
  ui_story_31200201_73_dialog_content = "Satu kali!",
  ui_story_31200201_74_dialog_content = "Maaf, itu salah.",
  ui_story_31200201_75_dialog_content = "Apa? Kalau jadi dia, aku pasti langsung bisa menemukannya dalam sekali percobaan! Bukan salahku kalau Michenny tidak sepintar aku!",
  ui_story_31200201_76_dialog_content = "Brock, kamu mendapat kartu merah sebagai peringatan. Tolong dicatat: kami tidak menoleransi serangan pribadi di kontes ini.",
