  ui_story_31200201_78_dialog_content = "Hedy! Silakan menjawab!",
  ui_story_31200201_79_dialog_content = "Dua kali. Kalau bola itu dibagi menjadi tiga kelompok berisi masing-masing tiga...",
  ui_story_31200201_80_dialog_content = "Kalau beruntung, kita bisa menemukan bola beratnya dalam dua kali percobaan.",
