  ui_story_31200201_82_dialog_content = "Wow... Kenapa sih aku tadi mau ikut segala?",
  ui_story_31200201_83_dialog_content = "Pertanyaan kedua adalah soal sejarah!",
  ui_story_31200201_84_dialog_content = "Di atas pulau melayang manakah kota Lumopolis berada? Mulai!",
  ui_story_31200201_85_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_31200201_86_dialog_content = "Oho! Kali ini, Michael berhasil menjadi orang pertama yang memencet bel! Apa jawabanmu?",
  ui_story_31200201_87_dialog_content = "...",
  ui_story_31200201_88_dialog_content = "Kalau tidak bisa langsung menjawab, yang lain boleh menjawab!",
  ui_story_31200201_89_dialog_content = "Anu... Jomu? A-aku tahu apa jawaban Michael! Dia ingin bilang...",
  ui_story_31200201_90_dialog_content = "Maaf, membantu kontestan lain juga dilarang!",
  ui_story_31200201_91_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_31200201_92_dialog_content = "Mudah sekali... Jawabannya adalah Azurite.",
  ui_story_31200201_93_dialog_content = "Selamat, Hedy! Lagi-lagi kamu benar!",
  ui_story_31200201_94_dialog_content = "Aduh, aku mengantuk sekali... Kenapa aku tak bisa menjawab pertanyaan-pertanyaan ini, sih...?",
