  ui_story_31200201_96_dialog_content = "Pertanyaan terakhir adalah soal sastra!",
  ui_story_31200201_97_dialog_content = "Pada pertemuan bangsawan di Lumopolis, para hadirin yang bertemu berjabat tangan tepat 45 kali.",
