  ui_story_31200201_99_dialog_content = "Pertanyaannya: berapa banyak jumlah orang yang hadir? Mulai!",
  ui_story_31200201_100_dialog_content = "<color=#e8d9bb>Ding!</color>",
  ui_story_31200201_101_dialog_content = "Pertama, aku ingin mengatakan bahwa para bangsawan Lumopolis jarang berjabat tangan. Kedua, ini jelas-jelas bukan pertanyaan soal sastra.",
  ui_story_31200201_102_dialog_content = "Maaf, jawabanmu salah.",
  ui_story_31200201_103_dialog_content = "...",
