  ui_story_31200201_105_dialog_content = "Mari kita lihat apakah PlayerName bisa menjawabnya! Silakan!",
  ui_story_31200201_106_option_content = "Sepuluh orang!",
  ui_story_31200201_107_dialog_content = "Selamat, PlayerName! Jawabanmu benar!",
  ui_story_31200201_108_dialog_content = "Sepertinya kamu tidak sebodoh yang kukira.",
  ui_story_31200201_109_option_content = "Tujuh orang!",
  ui_story_31200201_110_dialog_content = "Maaf, jawabanmu salah.",
  ui_story_31200201_111_dialog_content = "Jawabannya sepuluh orang, bukan tujuh...",
  ui_story_31200201_112_dialog_content = "Sayangnya... Karena Nona Hedy tiba-tiba menjawab dengan benar, pertanyaan ini menjadi tidak valid.",
  ui_story_31200201_113_dialog_content = "Dengan demikian, babak pertama dari kontes hari ini telah berakhir!",
  ui_story_31200201_114_dialog_content = "Michael, Brock, Philyshy, Taki... Maaf, kalian tereliminasi dari kontes ini!",
  ui_story_31200201_115_dialog_content = "...",
  ui_story_31200201_116_dialog_content = "Sial! Kalau saja ini adalah kontes binaraga atau semacamnya, aku pasti sudah menang!",
  ui_story_31200201_117_dialog_content = "Bangun, Philyshy. Kita tereliminasi.",
  ui_story_31200201_118_dialog_content = "Nyaaa... Hah? Kok aku ada di sini...?",
  ui_story_31200201_119_dialog_content = "Sebentar, Taki juga kalah? Aduh, tak kusangka aku buang-buang seratus Nightium untuk dia!",
  ui_story_31200201_120_dialog_content = "*Berdesah* Buang-buang waktu saja. Ayo kita pergi dari sini...",
  ui_story_31200201_121_dialog_content = "Hoi, Jomu. Separuh penontonmu sudah pergi, tuh.",
  ui_story_31200201_122_dialog_content = "Tidak apa-apa! Orang yang harus ada di sini masih ada!",
  ui_story_31200201_123_dialog_content = "Jangan lupa membayar upahku, Nak.",
  ui_story_31200201_124_dialog_content = "Aku tak akan lupa.",
  ui_story_31200201_125_dialog_content = "Babak terakhir masih belum dimulai?",
  ui_story_31200201_126_dialog_content = "Iya... Walaupun yang tersisa hanya kita berdua...",
  ui_story_31200201_127_dialog_content = "Sebelum kontes, kudengar kamu sangat cerdas seperti kontestan lain...",
  ui_story_31200201_128_dialog_content = "Tampaknya rumor itu tak sepenuhnya tidak berdasar.",
  ui_story_31200201_129_dialog_content = "O-orang-orang benar-benar mengatakan hal seperti itu tentang aku? Aduh, aku tersanjung...",
  ui_story_31200201_130_dialog_content = "Meski begitu, aku tak mau kalah darimu.",
  ui_story_31200201_131_dialog_content = "Nah, nyonya-nyonya dan tuan-tuan...",
  ui_story_31200201_132_dialog_content = "Mari kita mulai babak terakhir!",
  ui_story_31200201_133_dialog_content = "Kontestan: kalian siap?",
  ui_story_31200201_134_dialog_content = "Tentu saja.",
  ui_story_31200201_135_option_content = "Aku siap!",
  ui_story_31200201_136_dialog_content = "Peraturan di babak terakhir ini sangat mudah: setiap kontestan akan memilih topik untuk lawan, dan mereka harus menjawab pertanyaan tentang topik itu!",
  ui_story_31200201_137_dialog_content = "Nah, PlayerName... Silakan pilih topik untuk Hedy!",
  ui_story_31200201_138_dialog_content = "Hmm... Bagaimana kalau soal bahasa?",
  ui_story_31200201_139_dialog_content = "Baiklah! Kalau begitu, mari kita sambut tamu spesial: Tweety!",
  ui_story_31200201_140_dialog_content = "Hedy, tolong dengar perkataan Tweety baik-baik, dan terjemahkan dengan benar!",
  ui_story_31200201_141_dialog_content = "Hawo, semuanya! Senang wasanya bisa datang kemawi! Wow... Banyak sekawi owangnya! Sewu banget!",
  ui_story_31200201_142_dialog_content = "Halo, semuanya! Senang rasanya bisa datang kemari! Wow... Banyak sekali orangnya! Seru banget!",
  ui_story_31200201_143_dialog_content = "Eh? Nona ini cantik sekawi!",
  ui_story_31200201_144_dialog_content = "Eh? Nona ini cantik sekali!",
  ui_story_31200201_145_dialog_content = "Dia bahkan menirukan ekspresi Tweety dengan sempurna...",
  ui_story_31200201_146_dialog_content = "Benar sekali! Nah, sekarang giliran PlayerName!",
  ui_story_31200201_147_dialog_content = "Hedy, silakan pilih topik untuk PlayerName!",
  ui_story_31200201_148_dialog_content = "Kebudayaan.",
  ui_story_31200201_149_dialog_content = "Baiklah! Ini pertanyaannya!",
  ui_story_31200201_150_dialog_content = "Windward Forest, yang terletak di bagian selatan Northland, adalah rumah bagi pohon kuno yang dikenal sebagai \"Windward King\".",
  ui_story_31200201_151_dialog_content = "Pertanyaan: Pohon macam apakah \"Windward King\" itu?",
  ui_story_31200201_152_dialog_content = "A-aku... yakin pernah melihat pohon itu sebelumnya...",
  ui_story_31200201_153_dialog_content = "Tapi, di mana, ya?",
  ui_story_31200201_154_dialog_content = "Silakan menjawab!",
  ui_story_31200201_155_option_content = "Pohon ek?",
  ui_story_31200201_156_option_content = "Pohon dedalu?",
  ui_story_31200201_157_dialog_content = "Maaf, jawabanmu salah.",
  ui_story_31200201_158_dialog_content = "Semuanya, mari kita ucapkan selamat kepada Nona Hedy!",
  ui_story_31200201_159_dialog_content = "Juara pertama dari Bryte Cup Brain Battle pertama tak lain adalah... <color=#FFB400>Nona Hedy</color>!",
  ui_story_31200201_160_dialog_content = "Terima kasih, semuanya.",
  ui_story_31200201_161_dialog_content = "Wow! Selamat! Aku memilih dia, tahu? Hahaha!",
  ui_story_31200201_162_dialog_content = "Sekarang, kami akan secara acak memilih satu orang beruntung yang memilih Nona Hedy untuk menerima hadiah luar biasa atas dukungannya!",
  ui_story_31200201_163_dialog_content = "Dan nama orang yang beruntung itu adalah...",
  ui_story_31200201_164_dialog_content = "<color=#FFB400>PlayerName!</color>",
  ui_story_31200201_165_dialog_content = "PlayerName?!",
  ui_story_31200201_166_dialog_content = "H-Hedy? Selamat karena sudah menjadi pemenang. Sudah kuduga kamu bakal menang!",
  ui_story_31200201_167_dialog_content = "...",
  ui_story_31200201_168_dialog_content = "Terima kasih sudah memperbolehkanku berpartisipasi dalam kontes ini.",
  ui_story_31200201_169_dialog_content = "Tak pernah kusangka aku bakal menerima hadiah hari ini. Apalagi hadiah \"misterius\" begini.",
  ui_story_31200201_170_dialog_content = "Itu sarkasme, 'kan?",
  ui_story_31200201_171_dialog_content = "Hah?",
  ui_story_31200201_172_dialog_content = "Bahkan sebelum kontes dimulai... Kamu memilihku, ya?",
  ui_story_31200201_173_dialog_content = "Iya...",
  ui_story_31200201_174_dialog_content = "Jadi, kamu sengaja mengalah agar bisa mendapatkan hadiah misterius itu?",
  ui_story_31200201_175_dialog_content = "T-tidak, bukan begitu...",
  ui_story_31200201_176_dialog_content = "Ini tidak adil.",
  ui_story_31200201_177_dialog_content = "Aku tak mau menang kalau begini caranya... Ayo kita menghadap pihak penyelenggara dan meminta tanding tambahan!",
  ui_story_31200201_178_dialog_content = "(Kok bisa, sih? Aku benar-benar tidak tahu akan seperti apa pertanyaan terakhirnya...)",
  ui_story_31200201_179_dialog_content = "Hedy... Aku benar-benar mengira kamu bakal menang! Itu alasanku memilihmu!",
  ui_story_31200201_180_dialog_content = "Tapi, kenapa?",
  ui_story_31200201_181_dialog_content = "K-karena... Karena kamu pintar dan berpendidikan... Kalau ada yang pantas menang, kamulah orangnya!",
  ui_story_31200201_X181_dialog_content = "Kuharap kamu tidak salah paham, tapi aku selalu menganggapmu sebagai teman.",
  ui_story_31200201_X182_dialog_content = "Jadi... Entah siapa pun yang menang, itu tetap pantas dirayakan... Iya, 'kan?",
  ui_story_31200201_182_dialog_content = "Teman...?",
  ui_story_31200201_183_dialog_content = "Benar! Teman selalu ikut bahagia kalau yang lain menang dan sukses!",
  ui_story_31200201_184_dialog_content = "Jadi, meskipun mereka lawan, pencapaian mereka tetap membuat kita merasa bahagia!",
  ui_story_31200201_185_dialog_content = "Dengan begitu, bagaimanapun hasilnya, akan selalu ada kebahagiaan yang berlipat ganda untuk mereka! Iya, 'kan?",
  ui_story_31200201_186_dialog_content = "Kebahagiaan... berlipat ganda.",
  ui_story_31200201_187_dialog_content = "Nah, Hedy... Kamu mau ikut berbahagia dengan membuka hadiah misterius ini bersamaku tidak?",
  ui_story_31200201_188_dialog_content = "Eh, memangnya boleh...?",
  ui_story_31200201_189_dialog_content = "Ayolah! Mari kita buka bersama dan melihat isinya!",
  ui_story_31200201_190_dialog_content = "... Tentu.",
  ui_story_31200201_191_dialog_content = "*Bersiul* Ide pemilihan itu benar-benar menghasilkan banyak uang. Totalnya lebih dari seratus ribu Nightium, dan aku hampir tak perlu bersusah payah untuk mendapatkannya!",
  ui_story_31200201_192_dialog_content = "Wah, tak kusangka acara seperti ini akan jadi sangat populer! Harus kuakui...",
  ui_story_31200201_193_dialog_content = "Senang rasanya bisa menjadi juara sungguhan! Seratus ribu Nightium, hanya untukku seorang! Hahahaha...",
  ui_story_31200601_1_dialog_content = "Halo, untuk memastikan keamanan Anda...",
  ui_story_31200601_2_dialog_content = "Halo, untuk memastikan...",
  ui_story_31200601_3_dialog_content = "Halo, untuk...",
  ui_story_31200601_4_dialog_content = "Apakah ada gunanya membagikan brosur?",
  ui_story_31200601_5_dialog_content = "Bahkan tidak ada yang peduli.",
  ui_story_31200601_6_dialog_content = "M-Maaf! Aku seharusnya memikirkan ini lebih jauh.",
  ui_story_31200601_7_dialog_content = "Ini seharusnya menjadi acara untuk meningkatkan persahabatan faksi kita, namun...",
  ui_story_31200601_8_dialog_content = "Tidak perlu meminta maaf. Itu bukan salahmu.",
  ui_story_31200601_9_dialog_content = "Hanya saja saya tidak terbiasa berada di keramaian, apalagi dikelilingi oleh semua teknologi lama ini.",
  ui_story_31200601_10_dialog_content = "Jika saya tidak melakukan pekerjaan <color=#FFB400>sheriff</color> sekarang juga...",
  ui_story_31200601_11_dialog_content = "Apa? Tolong jangan...!",
  ui_story_31200601_12_dialog_content = "Saya tidak akan melakukannya, tetapi yang saya inginkan sekarang adalah menyelesaikan ini secepat mungkin.",
  ui_story_31200601_13_dialog_content = "Bagaimanapun, aku akan menahannya sementara itu.",
  ui_story_31200601_14_dialog_content = "Apakah Anda yakin, Nona Hedy?",
  ui_story_31200601_15_dialog_content = "Halo, untuk memastikan keselamatan Anda dan keamanan Kota Gannon, silakan ambil brosur ini. Terima kasih.",
  ui_story_31200601_16_dialog_content = "Hedi?",
  ui_story_31200601_17_dialog_content = "PlayerName?!",
  ui_story_31200601_18_dialog_content = "Aku tahu itu. Tidak ada orang lain yang akan memberi saya waktu.",
  ui_story_31200601_19_dialog_content = "Saya pikir saya salah orang, tapi itu benar-benar Anda.",
  ui_story_31200601_20_dialog_content = "Mengapa Anda membagikan brosur di Gannon?",
  ui_story_31200601_21_dialog_content = "Yah, saya juga tidak berharap ini terjadi ...",
  ui_story_31200601_22_dialog_content = "<color=#e8d9bb>Satu minggu yang lalu</color>",
  ui_story_31200601_23_dialog_content = "Saya menerima undangan dari Federasi Illumina untuk menyelenggarakan acara bersama Lumopolis.",
  ui_story_31200601_24_dialog_content = "Kali ini, Biro Keamanan dan kuil yang masing-masing akan mengirim perwakilan untuk terlibat dalam pertukaran budaya.",
  ui_story_31200601_25_dialog_content = "Mereka ingin kita memilih seseorang dengan lebih banyak <color=#FFB400>baik</color> image untuk bertindak sebagai sheriff selama sehari di Gannon.",
  ui_story_31200601_26_dialog_content = "Sehat, katamu...",
  ui_story_31200601_27_dialog_content = "Pittman adalah yang pertama keluar.",
  ui_story_31200601_28_dialog_content = "Diikuti oleh Matthieu.",
  ui_story_31200601_29_dialog_content = "Dan terakhir, saya.",
  ui_story_31200601_30_dialog_content = "Anda hanya mendapatkan semacam kesadaran diri pada saat-saat seperti ini.",
  ui_story_31200601_31_dialog_content = "Saya tidak mengerti mengapa badut ini akan mengecualikan saya.",
  ui_story_31200601_32_dialog_content = "Tapi bagaimanapun, pikiran berbaur dengan rakyat jelata membuatku muak.",
  ui_story_31200601_33_dialog_content = "Aku sangat sibuk akhir-akhir ini, jadi jangan hitung aku juga.",
  ui_story_31200601_34_dialog_content = "Erica mungkin blak-blakan, tetapi fakta adalah fakta. Saya tidak cocok untuk acara ini.",
  ui_story_31200601_35_dialog_content = "Sebenarnya, saya memiliki prospek yang baik dalam pikiran.",
  ui_story_31200601_36_dialog_content = "Saya tidak pernah membayangkan masalah seperti ini akan menarik bagi Anda, Irridon.",
  ui_story_31200601_37_dialog_content = "Aku harus melihatmu dalam cahaya baru.",
  ui_story_31200601_38_dialog_content = "Berhenti berbicara omong kosong.",
  ui_story_31200601_39_dialog_content = "Saya kebetulan melihat pos rekrutmen untuk sheriff sementara, dan orang ini langsung muncul di benak saya.",
  ui_story_31200601_40_dialog_content = "Meskipun saya tidak pernah melihat posting yang Anda sebutkan, saya pikir saya tahu apa yang Anda maksud.",
  ui_story_31200601_41_dialog_content = "Ini seperti Anda mendapat pencerahan tiba-tiba ... Ya, itu saja.",
  ui_story_31200601_42_dialog_content = "Mengapa kita tidak mengambil suara? Dengan begitu, siapapun yang terpilih tidak bisa menolak.",
  ui_story_31200601_43_dialog_content = "Saya mendapatkan perasaan bahwa Anda tidak baik entah bagaimana.",
  ui_story_31200601_44_dialog_content = "Meskipun begitu, saya untuk voting.",
  ui_story_31200601_45_dialog_content = "Kalau begitu mari kita putuskan dengan polling.",
  ui_story_31200601_46_dialog_content = "<color=#e8d9bb>Pagi ini</color>",
  ui_story_31200601_47_dialog_content = "Saya di sini untuk menjemput Anda, Nona Hedy!",
  ui_story_31200601_48_dialog_content = "Hah? Untuk apa?",
  ui_story_31200601_49_dialog_content = "Anda seharusnya menjadi sheriff hari ini. Sudahkah kamu lupa?",
  ui_story_31200601_50_dialog_content = "Huh, aku yakin dia sengaja lupa.",
  ui_story_31200601_51_dialog_content = "Aku tidak tuli, E-ri-ca.",
  ui_story_31200601_52_dialog_content = "Dan tidak, saya tidak lupa.",
  ui_story_31200601_53_dialog_content = "Hanya saja, aku terlalu sibuk akhir-akhir ini.",
  ui_story_31200601_54_dialog_content = "Anda telah menerima seragam Anda, kan? Apakah itu cocok?",
  ui_story_31200601_55_dialog_content = "Apakah Anda ingin mengubahnya di Illumina?",
  ui_story_31200601_56_dialog_content = "Ya, saya benar-benar tidak ingin mereka melihat saya dalam hal itu.",
  ui_story_31200601_57_dialog_content = "Baiklah, kalau begitu, ayo pergi!",
  ui_story_31200601_58_dialog_content = "Tidak percaya mereka semua memilih saya ketika saya tidak ada di sana ...",
  ui_story_31200601_59_dialog_content = "Aku yakin itu ide Erica.",
  ui_story_31200601_60_dialog_content = "Sebagai Ksatria Lumopolis, saya tidak pernah membayangkan akan pernah mengenakan seragam Illumina.",
  ui_story_31200601_61_dialog_content = "Semua orang mungkin berpikir aku aneh karena mengenakan pakaian yang sama sekali tidak pantas ini.",
  ui_story_31200601_62_dialog_content = "Itu sebabnya tidak ada yang mengambil brosur.",
  ui_story_31200601_63_dialog_content = "Tapi itu dibuat khusus untuk perwakilan Lumopolis untuk acara tersebut.",
  ui_story_31200601_64_dialog_content = "Jika menurut Anda itu tidak cocok, itu pasti salah saya karena tidak memberikan pengukuran yang tepat.",
  ui_story_31200601_65_dialog_content = "Saya gagal menyampaikan kualitas Anda ke Logistik ...",
  ui_story_31200601_66_dialog_content = "Aku merusak semuanya... maafkan aku...",
  ui_story_31200601_67_dialog_content = "T-Tidak, bukan itu maksudku!",
  ui_story_31200601_68_dialog_content = "Ini bukan salahmu. Aku terlalu histeris.",
  ui_story_31200601_69_dialog_content = "Saya tidak berpikir Anda melakukan kesalahan juga, Cordy, jadi jangan salahkan diri Anda sendiri.",
  ui_story_31200601_70_dialog_content = "Hal yang sama berlaku untuk Hedi. Saya pikir semua orang di kuil memilih Anda karena Anda adalah kandidat terbaik untuk pekerjaan itu.",
  ui_story_31200601_71_dialog_content = "Maksudku, aku bahkan tidak mengenalimu saat aku mengambil brosur itu!",
  ui_story_31200601_72_dialog_content = "Anda benar-benar terlihat seperti sheriff Gannon.",
  ui_story_31200601_73_dialog_content = "Saya rasa tidak ada yang perlu Anda khawatirkan.",
  ui_story_31200601_74_option_content = "Pakaian ini tidak terlihat aneh untukmu.",
  ui_story_31200601_75_dialog_content = "Anda benar-benar memancarkan pesona yang berbeda dari biasanya di dalamnya!",
  ui_story_31200601_76_option_content = "Kau sudah mempesona, Hedy.",
  ui_story_31200601_77_dialog_content = "Sekarang seragam sepenuhnya mencakup pesona khusus Anda juga.",
  ui_story_31200601_78_dialog_content = "Jika Anda bertanya kepada saya, semua orang menyukai Anda tidak peduli bagaimana penampilan Anda.",
  ui_story_31200601_79_dialog_content = "Terima kasih. Aku merasa jauh lebih baik mendengar kata-katamu.",
  ui_story_31200601_80_dialog_content = "Tapi pamflet...",
  ui_story_31200601_81_dialog_content = "Orang-orang mungkin terlalu sibuk untuk mengambilnya sekarang.",
  ui_story_31200601_82_dialog_content = "Mengapa Anda tidak menyelesaikan pekerjaan lain terlebih dahulu, dan saya akan membantu Anda membagikannya nanti?",
  ui_story_31200601_83_dialog_content = "Apa agenda selanjutnya, Cordy?",
  ui_story_31200601_84_dialog_content = "Pergi ke stasiun dan menyiarkan pesan keselamatan penumpang.",
  ui_story_31200601_85_dialog_content = "Jika itu tidak melibatkan saya berdiri di tengah orang banyak, saya merasa jauh lebih menyenangkan!",
  ui_story_31200601_86_dialog_content = "Tolong serahkan tugas itu padaku.",
  ui_story_31200601_87_dialog_content = "Anda benar-benar mengesankan. Semua orang dihibur oleh irama suara Anda yang fasih dan elegan!",
  ui_story_31200601_88_dialog_content = "Ini lebih seperti mendengarkan dongeng daripada pesan layanan publik.",
  ui_story_31200601_89_dialog_content = "Anda terpaku sepanjang waktu, dan itu berakhir sebelum Anda menyadarinya.",
  ui_story_31200601_90_dialog_content = "Ini cukup mudah bagi seseorang seperti saya yang pernah bekerja dengan Paduan Suara.",
  ui_story_31200601_94_dialog_content = "Tolong, seorang anak jatuh dari peron!",
  ui_story_31200601_96_dialog_content = "<color=#e8d9bb>Cho! Dentang, dentang, dentang...</color>",
  ui_story_31200601_97_dialog_content = "Oh tidak, keretanya datang!",
  ui_story_31200601_98_dialog_content = "Ambil selebaran, PlayerName!",
  ui_story_31200601_99_dialog_content = "Hentikan keretanya, Pompey! Aku harus menyelamatkan anak itu!",
  ui_story_31200601_100_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_31200601_101_dialog_content = "Cepat, Cordy, ayo ke peron!",
  ui_story_31200601_102_dialog_content = "Ya!",
  ui_story_31200601_103_dialog_content = "Terima kasih telah menyelamatkan anak saya. Aku tidak tahu bagaimana aku bisa membalasmu...",
  ui_story_31200601_104_dialog_content = "Aku hanya membalikkan punggungku sebentar dan sebelum aku menyadarinya, dia sudah jatuh.",
  ui_story_31200601_105_dialog_content = "Tolong lain kali lebih diperhatikan.",
  ui_story_31200601_106_dialog_content = "Ini tidak akan terjadi lagi! Terima kasih!",
  ui_story_31200601_108_dialog_content = "Sama-sama. Anaknya aman, itu yang terpenting.",
  ui_story_31200601_109_dialog_content = "Dia langsung beraksi ketika semua orang masih panik. Bagaimana luar biasa.",
  ui_story_31200601_110_dialog_content = "Kamu benar. Dan sepertinya dia seorang sheriff, tidak heran!",
  ui_story_31200601_112_dialog_content = "Ahem, karena semuanya baik-baik saja sekarang, aku harus pergi.",
  ui_story_31200601_113_dialog_content = "Apakah Anda malu, Nona Hedy? Saya tidak berharap Anda terlihat sangat imut ketika Anda malu!",
  ui_story_31200601_114_dialog_content = "... Aku tidak malu.",
  ui_story_31200601_115_dialog_content = "Apa selanjutnya di map, Cordy? Kita harus melanjutkan.",
  ui_story_31200601_116_dialog_content = "Hal terakhir adalah memberikan pembekalan publik tentang pekerjaan Anda hari ini di alun-alun stasiun.",
  ui_story_31200601_117_dialog_content = "Tidak masalah. Ayo pergi.",
  ui_story_31200601_118_dialog_content = "...",
  ui_story_31200601_119_dialog_content = "Ada apa, Hedi? Apakah kamu baik-baik saja?",
  ui_story_31200601_120_dialog_content = "Apakah Anda terluka menyelamatkan anak itu?",
  ui_story_31200601_121_dialog_content = "Tidak, aku tiba-tiba sangat gugup.",
  ui_story_31200601_122_dialog_content = "Logikanya, pembekalan itu seharusnya mudah bagi saya.",
  ui_story_31200601_123_dialog_content = "Tetapi ketika saya memikirkan kembali, tidak ada yang berjalan lancar hari ini.",
  ui_story_31200601_124_dialog_content = "Saya tidak bisa membagikan selebaran yang cukup, lalu ada kecelakaan di stasiun ...",
  ui_story_31200601_125_dialog_content = "Saya merasa stres dan cemas tidak seperti sebelumnya.",
  ui_story_31200601_126_dialog_content = "Mungkin mereka akan mengabaikan tanya jawab seperti yang mereka lakukan dengan brosur.",
  ui_story_31200601_127_dialog_content = "Jangan khawatir, Hedy, Anda memiliki kami.",
  ui_story_31200601_128_dialog_content = "Naik saja ke atas panggung dan lakukan pekerjaanmu. Pendengar akan datang.",
  ui_story_31200601_129_dialog_content = "PlayerName benar. Percaya pada pesonamu, Nona Hedy!",
  ui_story_31200601_130_dialog_content = "Anda akan memiliki kami berdua sebagai audiens setia Anda setidaknya!",
  ui_story_31200601_131_dialog_content = "Saya tidak berharap untuk mendapatkan dorongan dari Anda berdua ...",
  ui_story_31200601_132_dialog_content = "Baiklah... Aku mengerti.",
  ui_story_31200601_133_dialog_content = "Itu hanya pidato. Sepotong kue untuk seseorang yang luar biasa seperti saya.",
  ui_story_31200601_134_dialog_content = "Selamat sore semuanya. Saya Hedy, seorang hakim dari Lumopolis.",
  ui_story_31200601_135_dialog_content = "Merupakan kehormatan bagi saya untuk mengunjungi dan melayani Gannon sebagai sheriff satu hari.",
  ui_story_31200601_136_dialog_content = "Aku tahu tidak ada yang peduli...",
  ui_story_31200601_137_dialog_content = "Halo, untuk memastikan keselamatan Anda dan keamanan Kota Gannon, silakan ambil brosur ini. Terima kasih.",
  ui_story_31200601_138_dialog_content = "Dan tolong dengarkan juga pidato yang sedang berlangsung.",
  ui_story_31200601_139_dialog_content = "Dia seorang sheriff yang sangat pekerja keras dan sedang melaporkan pengalamannya sekarang.",
  ui_story_31200601_140_dialog_content = "Hmm? Adalah PlayerName membantu saya dengan promosi?",
  ui_story_31200601_141_dialog_content = "Hei, bukankah gadis di atas panggung itu adalah sheriff yang baru saja menyelamatkan seseorang di stasiun?",
  ui_story_31200601_142_dialog_content = "Ya, itu dia! Mari kita dengar apa yang dia katakan.",
  ui_story_31200601_143_dialog_content = "Orang-orang... benar-benar datang... Yah, kurasa aku akan memberikan semuanya sekarang!",
  ui_story_31200601_144_dialog_content = "Ahem. Untuk meningkatkan rasa aman serta keselamatan semua orang di Kota Gannon...",
  ui_story_31200601_145_dialog_content = "Saya melakukan tiga tugas berikut dalam peran saya sebagai sheriff...",
  ui_story_31200601_146_dialog_content = "<color=#e8d9bb>Sepuluh menit kemudian</color>",
  ui_story_31200601_147_dialog_content = "(Semua orang mendengarkan ...)",
  ui_story_31200601_148_dialog_content = "(Hedy yang percaya diri benar-benar unggul dalam segala hal.)",
  ui_story_31200601_149_dialog_content = "Saya sangat menghargai semua dukungan dan pengakuan Anda, dan saya akan menerapkan apa yang saya pelajari dalam tugas saya sendiri mulai saat ini.",
  ui_story_31200601_150_dialog_content = "Itu pidato saya. Terima kasih untuk semua Gannon sekali lagi.",
  ui_story_31200601_151_dialog_content = "Anda melakukannya dengan baik!",
  ui_story_31200601_152_dialog_content = "Mengapa tidak tinggal sebagai sheriff tetap?",
  ui_story_31200601_153_dialog_content = "Pidato yang bagus, Hedy!",
  ui_story_31200601_154_dialog_content = "Lihat, bahkan semua selebaran telah diambil.",
  ui_story_31200601_155_dialog_content = "Sayang sekali Anda tidak mendapatkan kesempatan lain untuk membagikannya sendiri.",
  ui_story_31200601_156_dialog_content = "Anda benar-benar semua tugas Anda dengan sempurna. Saya kira itu berarti acara telah berakhir dengan sukses!",
  ui_story_31200601_157_dialog_content = "Itu Nona Hedy yang saya kenal!",
  ui_story_31200601_158_dialog_content = "Terima kasih, PlayerName dan Cordy.",
  ui_story_31200601_159_dialog_content = "Aku tahu aku berhasil menyelesaikan semuanya hari ini hanya karena aku memiliki kalian berdua.",
  ui_story_31200601_160_dialog_content = "Saya merasa sedikit down sebelumnya.",
  ui_story_31200601_161_dialog_content = "Tapi secara keseluruhan, tidak buruk menjadi sheriff.",
  ui_story_31200601_162_dialog_content = "Dan saya pikir seragam itu juga cocok untuk saya.",
  ui_story_31200601_163_dialog_content = "<color=#e8d9bb>Sehari kemudian</color>",
  ui_story_31200601_164_dialog_content = "Hei, lihat siapa yang kembali.",
  ui_story_31200601_165_dialog_content = "Anda terlihat dalam suasana hati yang baik, Hedy. Acara berjalan dengan baik, saya kira?",
  ui_story_31200601_166_dialog_content = "Dia mungkin tidak akan mengakuinya, tapi aku tahu dia sangat menyukai seragam itu.",
  ui_story_31200601_167_dialog_content = "Aku bisa merasakan betapa hangat dan kabur yang dia rasakan di dalam ketika dia berada di dalamnya.",
  ui_story_31200601_168_dialog_content = "Saya katakan sebelumnya, Erica, bahwa saya dapat mendengar semua yang Anda katakan.",
  ui_story_31200601_169_dialog_content = "Omong-omong, kapan Anda keluar dari gaya funky itu?",
  ui_story_31200601_170_dialog_content = "Yah, kami adalah Divisi Investigasi Heretics, dan ini satu-satunya cara kami bisa mendekati mereka.",
  ui_story_31200601_171_dialog_content = "Pakaian ini memungkinkan kita mendekati kebenaran dunia ini.",
  ui_story_31200601_172_dialog_content = "Sulit untuk menyerah.",
  ui_story_31200601_173_dialog_content = "Apa pun yang harus saya lakukan dengan Anda ...",
  ui_story_31200601_174_dialog_content = "Ayo, beri saya gambaran tentang semua pekerjaan yang Anda selesaikan kemarin.",
  ui_story_31200601_175_dialog_content = "Tidak bisakah kita terus berbicara tentang pakaian, Nona Hedy?",
